// data lives in data/*.json (photos.json is generated by tools/)
const load=f=>fetch("data/"+f,{cache:"no-cache"}).then(r=>{if(!r.ok)throw new Error(f+" "+r.status);return r.json()});
let GEO,TRIPS,PHOTOS;
try{[GEO,TRIPS,PHOTOS]=await Promise.all(["geo.json","trips.json","photos.json"].map(load))}
catch(e){document.getElementById("app").innerHTML=`<p style="padding:48px 0">数据加载失败 / Failed to load data: ${e.message}</p>`;throw e}
TRIPS=TRIPS.filter(t=>!t.draft);  // drafts are still being reviewed
TRIPS.forEach(tr=>tr.days.forEach(d=>{const p=(PHOTOS[tr.id]||{})[d.d];if(p){d.photos=p.items;d.cover=p.cover||0}}));
const MOOD={air:["#9DB7D5","#E4ECF4"],night:["#1C2440","#46557F"],city:["#B9C3CC","#77838F"],mountain:["#A9C1D9","#66806A"],temple:["#D6C7AE","#8A5A3C"],
 snow:["#C9D6E2","#F4F7FA"],garden:["#B9CBA4","#687F52"],sea:["#AFCFE0","#3B7894"],lake:["#C3D6DE","#6893A3"],torii:["#EDBE95","#B4452F"],
 bamboo:["#C9DBA9","#4D7640"],onsen:["#DAD5CB","#9AA5A2"],dome:["#DCC9A6","#56779A"],ruins:["#E7D6B2","#B4955F"],terrace:["#DDEFF0","#8FCBCF"],
 theater:["#E6D3AE","#A5824F"],cave:["#EDCC9F","#B3805A"],mosaic:["#CBA97C","#6C4A33"],desert:["#E9CB97","#B5834A"],tea:["#D2E2B4","#5A8747"]};
const NS="http://www.w3.org/2000/svg";
// one language setting shared with the rest of yanxia.art; first visit follows the browser
let lang=/^zh\b/i.test(navigator.language||"")?"zh":"en";try{const s=localStorage.getItem("lang");if(s==="zh"||s==="en")lang=s}catch(e){}
const T=o=>`<span class="zh">${o.zh}</span><span class="en">${o.en}</span>`;

// map symbols
const defs=document.getElementById("defs");
Object.entries(GEO).forEach(([k,g])=>{
  const s=document.createElementNS(NS,"symbol");s.id="land-"+k;s.setAttribute("viewBox",`0 0 ${g.W} ${g.H}`);
  s.innerHTML=`<path class="land-o" d="${g.other}"/><path class="land-main" d="${g.main}"/>`;defs.appendChild(s);
});
function routeD(trip,upto){const g=GEO[trip.geo];const seq=[];trip.days.slice(0,upto).forEach(d=>d.s.forEach(k=>{if(seq[seq.length-1]!==k)seq.push(k)}));return seq.length?"M"+seq.map(k=>g.stops[k].x+","+g.stops[k].y).join("L"):""}
function mapSVG(trip,{cls,now=[],labels=[],sw=1.5,r=3,full=true}){
  const g=GEO[trip.geo];
  const d=routeD(trip,trip.days.length);
  let dots="";const seen=new Set();trip.days.forEach(dd=>dd.s.forEach(k=>seen.add(k)));
  if(full)seen.forEach(k=>{if(!now.includes(k))dots+=`<circle class="dot" cx="${g.stops[k].x}" cy="${g.stops[k].y}" r="${r}"/>`});
  now.forEach(k=>dots+=`<circle class="dot now" cx="${g.stops[k].x}" cy="${g.stops[k].y}" r="${r*3.2}" stroke-width="${sw}"/>`);
  let lbl="";labels.forEach(k=>{const p=g.stops[k];lbl+=`<text class="olbl" x="${p.x+10}" y="${p.y+5}"><tspan class="zh">${p.zh}</tspan><tspan class="en">${p.en}</tspan></text>`});
  return `<svg class="${cls}" viewBox="0 0 ${g.W} ${g.H}" role="img" aria-label="map"><use href="#land-${trip.geo}" width="${GEO[trip.geo].W}" height="${GEO[trip.geo].H}"/><path class="rt" d="${d}" stroke-width="${sw}" opacity="${now.length?.35:.9}"/>${dots}${lbl}</svg>`;
}
function placeholder(mood,place,big){
  const [a,b]=MOOD[mood]||MOOD.city;
  return `<div class="ph" style="background:linear-gradient(180deg,${a} 0%,${a} 52%,${b} 53%,${b} 100%)"><span><span class="zh">照片占位：</span><span class="en">Photo: </span>${T(place)}</span></div>`;
}
function photos(trip,d){
  if(d.photos&&d.photos.length){const c=d.cover||0;const ord=[d.photos[c],...d.photos.filter((_,j)=>j!==c)];const extra=ord.length-3;
    return `<div class="photos">${ord.slice(0,3).map((p,j)=>`<div class="ph"><img src="${p.t}" alt="${p[lang]}" loading="lazy">${j===2&&extra>0?`<span class="more">+${extra}</span>`:""}</div>`).join("")}</div>`}
  const g=GEO[trip.geo];const pl=d.s.length?d.s.filter((k,i,a)=>a.indexOf(k)===i):[];
  const names=pl.map(k=>g.stops[k]);
  const air={zh:"机场",en:"Airport"};
  const n0=names[0]||air,n1=names[1]||names[0]||air,n2=names[2]||names[names.length-1]||air;
  return `<div class="photos">${placeholder(d.m,n0,1)}${placeholder(d.m,n1)}${placeholder(d.m,n2)}</div>`;
}

const STOPDAYS={};TRIPS.forEach(tr=>{const m={};tr.days.forEach((d,i)=>d.s.forEach(k=>{(m[k]=m[k]||[]);if(!m[k].includes(i))m[k].push(i)}));STOPDAYS[tr.id]=m});
const isDark=()=>document.documentElement.dataset.theme==="dark"||(document.documentElement.dataset.theme!=="light"&&matchMedia("(prefers-color-scheme: dark)").matches);
const reduce=()=>matchMedia("(prefers-reduced-motion: reduce)").matches;
let cur=null,curDay=-1;

// the overview route, drawn leg by leg: colour deepens from start to finish, an arrow mid-leg shows direction,
// and long transfers (a flight, a day on trains) are dashed so they don't read as a road
function routeLegs(trip){
  const g=GEO[trip.geo],seq=[];trip.days.forEach(d=>d.s.forEach(k=>{if(seq[seq.length-1]!==k)seq.push(k)}));
  const n=seq.length-1;let lines="",arrows="";
  for(let i=0;i<n;i++){const a=g.stops[seq[i]],b=g.stops[seq[i+1]],len=Math.hypot(b.x-a.x,b.y-a.y);if(len<.5)continue;
    const col=`color-mix(in oklab,var(--route) ${Math.round(28+72*(n>1?i/(n-1):1))}%,var(--paper))`,far=len>g.W*.25;
    lines+=`<line class="leg" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" style="stroke:${col}" stroke-width="${far?1.6:2.4}" vector-effect="non-scaling-stroke"${far?' stroke-dasharray="6 5"':""}/>`;
    arrows+=`<path class="arr" d="M-4.5,-3.6L4.5,0L-4.5,3.6Z" style="fill:${col}" data-x="${(a.x+b.x)/2}" data-y="${(a.y+b.y)/2}" data-a="${(Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI).toFixed(1)}" data-l="${len.toFixed(1)}"/>`}
  return lines+arrows;
}
function overviewSVG(trip){
  const g=GEO[trip.geo];const anchors=["vancouver","toronto","nyc","chicago","austin","orlando","atlanta","sapporo","tokyo","kyoto","beppu","istanbul","antalya","uchisar","van","trabzon","kars","madrid","sevilla","barcelona","paris","rome","berlin","prague","munich","krakow"];
  let s=`<svg class="overview" viewBox="0 0 ${g.W} ${g.H}" role="group" aria-label="${lang==="zh"?"路线图，可点击地点":"Route map, points are clickable"}"><use href="#land-${trip.geo}" width="${GEO[trip.geo].W}" height="${GEO[trip.geo].H}"/>${routeLegs(trip)}`;
  Object.keys(STOPDAYS[trip.id]).forEach(k=>{const p=g.stops[k];
    s+=`<g class="stop" data-k="${k}" tabindex="0" role="button" aria-label="${p[lang]}"><circle class="dot" cx="${p.x}" cy="${p.y}" r="4"/></g>`});
  Object.keys(STOPDAYS[trip.id]).forEach(k=>{const p=g.stops[k];s+=`<text class="olbl${anchors.includes(k)?' anchor':''}" data-x="${p.x}" data-y="${p.y}" x="${p.x+10}" y="${p.y+6}" pointer-events="none">${p[lang]}</text>`});
  return s+"</svg>";
}

function clamp(x,a,b){return Math.max(a,Math.min(b,x))}
function panZoom(svg,o){
  const ptrs=new Map();let startV=null,startP=null,moved=false,pinch=null,suppress=false;
  const rect=()=>svg.getBoundingClientRect();
  const k=()=>{const r=rect(),v=o.get();return Math.max(v[2]/r.width,v[3]/r.height)};
  const toSvg=(cx,cy)=>{const r=rect(),v=o.get(),s=k();const ox=r.left+(r.width-v[2]/s)/2,oy=r.top+(r.height-v[3]/s)/2;return[v[0]+(cx-ox)*s,v[1]+(cy-oy)*s]};
  const fix=v=>{const cx=clamp(v[0]+v[2]/2,0,o.W),cy=clamp(v[1]+v[3]/2,0,o.H);return[cx-v[2]/2,cy-v[3]/2,v[2],v[3]]};
  const zoomAt=(cx,cy,f)=>{const v=o.get();const w=clamp(v[2]*f,o.minW,o.maxW);f=w/v[2];const[px,py]=toSvg(cx,cy);o.set(fix([px-(px-v[0])*f,py-(py-v[1])*f,v[2]*f,v[3]*f]))};
  const active=e=>o.touchSingle||e.pointerType!=="touch"||ptrs.size>=2;
  svg.addEventListener("pointerdown",e=>{if(e.button>0)return;ptrs.set(e.pointerId,[e.clientX,e.clientY]);moved=false;
    if(ptrs.size===1){startV=o.get().slice();startP=[e.clientX,e.clientY];svg._pid=e.pointerId}
    if(ptrs.size===2){const[a,b]=[...ptrs.values()];pinch={d:Math.hypot(a[0]-b[0],a[1]-b[1]),m:[(a[0]+b[0])/2,(a[1]+b[1])/2]};o.onStart&&o.onStart()}});
  svg.addEventListener("pointermove",e=>{if(!ptrs.has(e.pointerId))return;ptrs.set(e.pointerId,[e.clientX,e.clientY]);
    if(ptrs.size>=2&&pinch){const[a,b]=[...ptrs.values()];const d=Math.hypot(a[0]-b[0],a[1]-b[1]),m=[(a[0]+b[0])/2,(a[1]+b[1])/2];
      const s=k();const v=o.get();o.set(fix([v[0]-(m[0]-pinch.m[0])*s,v[1]-(m[1]-pinch.m[1])*s,v[2],v[3]]));zoomAt(m[0],m[1],pinch.d/d);pinch={d,m};moved=true;return}
    if(!active(e)||!startP)return;const dx=e.clientX-startP[0],dy=e.clientY-startP[1];
    if(!moved&&Math.hypot(dx,dy)<4)return;if(!moved){moved=true;svg.classList.add("dragging");try{svg.setPointerCapture(e.pointerId)}catch(_){}o.onStart&&o.onStart()}
    const r=rect(),s=Math.max(startV[2]/r.width,startV[3]/r.height);o.set(fix([startV[0]-dx*s,startV[1]-dy*s,startV[2],startV[3]]))});
  const up=e=>{ptrs.delete(e.pointerId);if(ptrs.size<2)pinch=null;if(ptrs.size===1){const p=[...ptrs.values()][0];startP=p;startV=o.get().slice()}
    if(ptrs.size===0){svg.classList.remove("dragging");if(moved){suppress=true;setTimeout(()=>suppress=false,0);o.onEnd&&o.onEnd()}startP=null}};
  svg.addEventListener("pointerup",up);svg.addEventListener("pointercancel",up);
  svg.addEventListener("click",e=>{if(suppress||moved){e.stopPropagation();e.preventDefault();moved=false}},true);
  svg.addEventListener("wheel",e=>{if(o.ctrlWheel&&!(e.ctrlKey||e.metaKey)){o.hint&&o.hint();return}
    e.preventDefault();o.onStart&&o.onStart();zoomAt(e.clientX,e.clientY,Math.exp(e.deltaY*(e.deltaMode?0.05:0.0018)));clearTimeout(svg._we);svg._we=setTimeout(()=>o.onEnd&&o.onEnd(),120)},{passive:false});
  svg.addEventListener("dblclick",e=>{e.preventDefault();zoomAt(e.clientX,e.clientY,0.5);o.onEnd&&o.onEnd()});
  return{zoomCenter:f=>{const r=rect();zoomAt(r.left+r.width/2,r.top+r.height/2,f);o.onEnd&&o.onEnd()}};
}
function collide(svg,sel,priority){
  const ls=[...svg.querySelectorAll(sel)].filter(l=>l.style.display!=="none"||true);
  ls.sort((a,b)=>priority(b)-priority(a));const kept=[];
  ls.forEach(l=>{l.style.display="";if(l.style.visibility==="hidden")return;const r=l.getBoundingClientRect();if(!r.width)return;
    const hit=kept.some(k=>!(r.right<k.left||r.left>k.right||r.bottom<k.top||r.top>k.bottom));
    if(hit&&priority(l)<2)l.style.display="none";else kept.push(r)});
}

function tileSVG(trip,i){
  const g=GEO[trip.geo],d=trip.days[i];const now=[...new Set(d.s)];
  const xs=now.map(k=>g.stops[k].x),ys=now.map(k=>g.stops[k].y);
  let x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);
  const ar=16/10,minW=g.W*0.05;let w=Math.max(x1-x0,minW)*1.5,h=Math.max(y1-y0,minW/ar)*1.5;if(w/h<ar)w=h*ar;else h=w/ar;
  const vb=[(x0+x1)/2-w/2,(y0+y1)/2-h/2,w,h],s=w/100;
  const prev=i>0&&trip.days[i-1].s.length?[trip.days[i-1].s[trip.days[i-1].s.length-1]]:[];
  const seq=[];[...prev,...d.s].forEach(k=>{if(seq[seq.length-1]!==k)seq.push(k)});
  let o=`<svg class="tile" viewBox="${vb.map(n=>n.toFixed(1)).join(" ")}" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${now.map(k=>g.stops[k][lang]).join(", ")}"><use href="#land-${trip.geo}" width="${g.W}" height="${g.H}"/>`;
  o+=`<path class="rt" d="${routeD(trip,trip.days.length)}" stroke-width="1" vector-effect="non-scaling-stroke" opacity=".3"/>`;
  if(seq.length>1)o+=`<path class="rt-day" d="M${seq.map(k=>g.stops[k].x+","+g.stops[k].y).join("L")}" stroke-width="2.5" vector-effect="non-scaling-stroke"/>`;
  now.forEach((k,j)=>{const p=g.stops[k];o+=`<circle class="dot now" cx="${p.x}" cy="${p.y}" r="${2.6*s}" stroke-width="1.2" vector-effect="non-scaling-stroke"/>`+(now.length>1?`<text class="num" x="${p.x}" y="${p.y}" font-size="${3*s}">${j+1}</text>`:"")+`<text class="tl" data-j="${j}" x="${p.x+3.4*s}" y="${p.y+1.6*s}" font-size="${5*s}" stroke-width="${1.4*s}">${p[lang]}</text>`});
  return o+"</svg>";
}
function render(){
  const trip=cur;
  document.documentElement.style.setProperty("--accent",trip.accent[isDark()?1:0]);
  document.getElementById("tabs").innerHTML=TRIPS.map(t=>`<a href="#${t.id}"${t===trip?' aria-current="page"':""}>${T(t.tab)}</a>`).join("");
  let h=`<section class="hero"><div><h1>${T(trip.title)}</h1><p class="span">${T(trip.span)}</p><p class="lede">${T(trip.lede)}</p>
    <p class="note">${T({zh:"路线由浅到深、箭头指向前进方向，虚线是长途转移。把鼠标移到地图上的点可以预览，点击进入那一天；没有照片的日子，用当天的地图代替。",en:"The route darkens from start to finish and arrows point the way; dashed lines are long transfers. Hover a point to preview it, click to open that day; days without photos show the day's map instead."})}</p></div>
    <div class="ovwrap">${overviewSVG(trip)}<div class="mapctl"><button type="button" data-z="in" aria-label="Zoom in">+</button><button type="button" data-z="out" aria-label="Zoom out">−</button><button type="button" data-z="reset" aria-label="Reset map">⟲</button></div><div class="maphint">${lang==='zh'?'按住 Ctrl 或 ⌘ 再滚动来缩放':'Hold Ctrl or ⌘ and scroll to zoom'}</div></div></section>`;
  let ch=0;
  trip.days.forEach((d,i)=>{
    if(d.ch!==ch){ch=d.ch;const c=trip.days.filter(x=>x.ch===ch);h+=`<div class="chapter"><h2>${T(trip.chapters[ch])}</h2><span>${c[0].d} – ${c[c.length-1].d}</span></div>`}
    const kind=d.photos?"":(d.s.length?" nophoto":" textonly");h+=`<article class="day${kind}" id="day-${i}" data-i="${i}">${d.photos?photos(trip,d):(d.s.length?tileSVG(trip,i):"")}<div class="meta">
      <div class="dhead"><p class="date">${d.d}${d.n?`<small>${T({zh:d.n+" 晚",en:d.n+" nights"})}</small>`:""}</p>${d.s.length?mapSVG(trip,{cls:"loc",now:d.s,sw:3,r:5,full:false}):""}</div>
      <h3>${T({zh:d.zh,en:d.en})}</h3><p>${T({zh:d.bz,en:d.be})}</p>
      ${d.h?`<p class="stay">${T({zh:"住",en:"Stay"})}：${d.h}</p>`:""}
      <button class="open" type="button" data-i="${i}">${d.s.length?T({zh:"在地图上看这一天",en:"Open this day on the map"}):T({zh:"打开这一天",en:"Open this day"})}</button></div></article>`;
  });
  const idx=TRIPS.indexOf(trip),prev=TRIPS[idx-1],next=TRIPS[idx+1];
  h+=`<nav class="pager">${prev?`<a href="#${prev.id}"><small>${T({zh:"上一程",en:"Previous"})}</small><strong>${T(prev.title)}</strong></a>`:""}${next?`<a class="r" href="#${next.id}"><small>${T({zh:"下一程",en:"Next"})}</small><strong>${T(next.title)}</strong></a>`:""}</nav>`;
  const app=document.getElementById("app");app.innerHTML=h;
  document.title=trip.title[lang];
  // interactions
  app.querySelectorAll(".day .photos,.day .tile,.day .loc,.day .open").forEach(el=>el.addEventListener("click",()=>go(+el.closest(".day").dataset.i)));
  requestAnimationFrame(()=>app.querySelectorAll(".tile").forEach(sv=>collide(sv,".tl",l=>l.dataset.j==="0"?2:1)));
  const tip=document.getElementById("tip");const ov=app.querySelector(".overview");const g=GEO[trip.geo];
  const near=(cx,cy)=>{const m=ov.getScreenCTM();if(!m)return[];const out=[];
    Object.keys(STOPDAYS[trip.id]).forEach(k=>{const p=g.stops[k];const sx=m.a*p.x+m.c*p.y+m.e,sy=m.b*p.x+m.d*p.y+m.f;const dd=Math.hypot(sx-cx,sy-cy);if(dd<16)out.push([dd,k])});
    return out.sort((a,b)=>a[0]-b[0]).map(x=>x[1])};
  let hov=[];
  const mark=ks=>ov.querySelectorAll("g.stop").forEach(el=>el.querySelector(".dot").style.fill=ks.includes(el.dataset.k)?"var(--accent)":"");
  const show=(ks,x,y)=>{
    const ds=[...new Set(ks.flatMap(k=>STOPDAYS[trip.id][k]))].sort((a,b)=>a-b);const d0=trip.days[ds[0]];const [a,b]=MOOD[d0.m]||MOOD.city;
    const names=ks.map(k=>g.stops[k][lang]).join(lang==="zh"?"、":", ");
    const cp=ds.map(i=>trip.days[i]).find(x=>x.photos);tip.innerHTML=`${cp?`<div class="sw" style="background:url(${cp.photos[cp.cover||0].t}) center/cover"></div>`:""}<div class="tb"><b>${names}</b><ul>${ds.slice(0,6).map(i=>`<li><i>${trip.days[i].d}</i>${trip.days[i][lang]}</li>`).join("")}${ds.length>6?`<li><i></i>…</li>`:""}</ul><small>${lang==="zh"?"点击进入 "+d0.d:"Click to open "+d0.d}</small></div>`;
    tip.classList.add("on");const w=240,hgt=tip.offsetHeight;let L=x+16,Tp=y+16;if(L+w>innerWidth-8)L=x-w-16;if(Tp+hgt>innerHeight-8)Tp=y-hgt-16;
    tip.style.left=L+"px";tip.style.top=Math.max(8,Tp)+"px";mark(ks)};
  const hide=()=>{tip.classList.remove("on");mark([]);hov=[]};
  ov.addEventListener("mousemove",e=>{hov=near(e.clientX,e.clientY);ov.style.cursor=hov.length?"pointer":"";if(hov.length)show(hov,e.clientX,e.clientY);else{tip.classList.remove("on");mark([])}});
  ov.addEventListener("mouseleave",hide);
  ov.addEventListener("click",e=>{const ks=near(e.clientX,e.clientY);if(!ks.length)return;hide();
    go(Math.min(...ks.flatMap(k=>STOPDAYS[trip.id][k])))});
  ov.querySelectorAll("g.stop").forEach(el=>{const k=el.dataset.k;
    el.addEventListener("focus",()=>{const r=el.getBoundingClientRect();show([k],r.right,r.top)});
    el.addEventListener("blur",hide);
    el.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();hide();go(STOPDAYS[trip.id][k][0])}})});
  // pan & zoom on overview
  let ovb=[0,0,g.W,g.H];
  const lbls=[...ov.querySelectorAll(".olbl")],dots=[...ov.querySelectorAll(".dot")],arrs=[...ov.querySelectorAll(".arr")];
  const setOV=v=>{ovb=v;ov.setAttribute("viewBox",v.map(n=>n.toFixed(1)).join(" "));const s=v[2]/g.W;
    dots.forEach(d=>d.setAttribute("r",4*Math.max(s,.35)));
    const r=ov.getBoundingClientRect(),px=r.width?Math.min(r.width/v[2],r.height/v[3]):1;  // screen px per map unit
    arrs.forEach(a=>{a.setAttribute("transform",`translate(${a.dataset.x},${a.dataset.y}) rotate(${a.dataset.a}) scale(${1.25/px})`);a.style.display=a.dataset.l*px<42?"none":""});
    lbls.forEach(l=>{l.style.fontSize=(20*s)+"px";l.style.strokeWidth=(6*s)+"px";l.setAttribute("x",+l.dataset.x+10*s);l.setAttribute("y",+l.dataset.y+6*s)})};
  const relabel=()=>{const zoomed=ovb[2]<g.W*0.75;lbls.forEach(l=>l.style.visibility=(zoomed||l.classList.contains("anchor"))?"":"hidden");
    collide(ov,".olbl",l=>l.classList.contains("anchor")?1:0)};
  const hintEl=app.querySelector(".maphint");let ht;
  const ctl=panZoom(ov,{W:g.W,H:g.H,minW:g.W*0.06,maxW:g.W*1.2,ctrlWheel:true,touchSingle:false,get:()=>ovb,
    set:v=>{hide();setOV(v)},onEnd:relabel,hint:()=>{hintEl.classList.add("on");clearTimeout(ht);ht=setTimeout(()=>hintEl.classList.remove("on"),1100)}});
  app.querySelectorAll(".ovwrap .mapctl button").forEach(b=>b.addEventListener("click",()=>{const z=b.dataset.z;
    if(z==="in")ctl.zoomCenter(.6);else if(z==="out")ctl.zoomCenter(1/.6);else{setOV([0,0,g.W,g.H]);relabel()}}));
  setOV(ovb);requestAnimationFrame(relabel);
}

// ---------- detail view ----------
const detail=document.getElementById("detail"),dmap=document.getElementById("dmap");
let vb=null,anim=0;
function go(i){location.hash=cur.id+"/"+cur.days[i].d}
function dayBBox(trip,i){
  const g=GEO[trip.geo];const d=trip.days[i];let ks=d.s.slice();
  if(!ks.length){const near=(trip.days[i-1]||trip.days[i+1]);ks=near?near.s.slice(-1):[]}
  const xs=ks.map(k=>g.stops[k].x),ys=ks.map(k=>g.stops[k].y);
  let x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);
  const minW=g.W*0.075;let w=Math.max(x1-x0,minW)*1.6,h=Math.max(y1-y0,minW*0.7)*1.6;
  const box=dmap.getBoundingClientRect();const ar=box.width&&box.height?box.width/box.height:1.2;
  if(w/h<ar)w=h*ar;else h=w/ar;
  const cx=(x0+x1)/2,cy=(y0+y1)/2;return [cx-w/2,cy-h/2,w,h];
}
function setVB(v){vb=v;dmap.setAttribute("viewBox",v.map(n=>n.toFixed(1)).join(" "));
  const s=v[2]/100;dmap.querySelectorAll(".dot").forEach(c=>c.setAttribute("r",(c.classList.contains("now")?1.9:0.9)*s));
  dmap.querySelectorAll(".num").forEach(n=>n.setAttribute("font-size",2*s));
  dmap.querySelectorAll(".dlbl").forEach(n=>{n.setAttribute("font-size",(n.classList.contains("minor")?2.3:3)*s);n.setAttribute("stroke-width",.9*s);n.setAttribute("x",+n.dataset.x+(2.6*s));n.setAttribute("y",+n.dataset.y+(1*s))});
}
function placeLabels(){collide(dmap,".dlbl",l=>l.classList.contains("minor")?0:(l.dataset.j==="0"?2:1.5))}
function flyTo(target){
  cancelAnimationFrame(anim);
  if(!vb||reduce()){setVB(target);placeLabels();return}
  const from=vb.slice(),t0=performance.now(),D=650;
  const step=now=>{const p=Math.min(1,(now-t0)/D),e=p<.5?4*p*p*p:1-Math.pow(-2*p+2,3)/2;
    setVB(from.map((f,j)=>f+(target[j]-f)*e));if(p<1)anim=requestAnimationFrame(step);else placeLabels()};
  anim=requestAnimationFrame(step);
}
function buildDetailMap(trip,i){
  const g=GEO[trip.geo];const d=trip.days[i];
  const prevLast=i>0&&trip.days[i-1].s.length?[trip.days[i-1].s[trip.days[i-1].s.length-1]]:[];
  const seq=[];[...prevLast,...d.s].forEach(k=>{if(seq[seq.length-1]!==k)seq.push(k)});
  const dayD=seq.length>1?"M"+seq.map(k=>g.stops[k].x+","+g.stops[k].y).join("L"):"";
  let s=`<use href="#land-${trip.geo}" width="${GEO[trip.geo].W}" height="${GEO[trip.geo].H}"/><path class="rt" d="${routeD(trip,trip.days.length)}" stroke-width="1.2" vector-effect="non-scaling-stroke" opacity=".35"/>`;
  if(dayD)s+=`<path class="rt-day" d="${dayD}" stroke-width="3" vector-effect="non-scaling-stroke"/>`;
  const nowSet=[...new Set(d.s)];
  Object.keys(STOPDAYS[trip.id]).forEach(k=>{if(nowSet.includes(k))return;const p=g.stops[k];
    s+=`<circle class="dot" data-k="${k}" cx="${p.x}" cy="${p.y}" r="1"><title>${p[lang]}</title></circle><text class="dlbl minor" data-x="${p.x}" data-y="${p.y}" x="${p.x}" y="${p.y}">${p[lang]}</text>`});
  nowSet.forEach((k,j)=>{const p=g.stops[k];
    s+=`<circle class="dot now" cx="${p.x}" cy="${p.y}" r="1" stroke-width="1.5" vector-effect="non-scaling-stroke"/><text class="num" x="${p.x}" y="${p.y}">${j+1}</text><text class="dlbl" data-j="${j}" data-x="${p.x}" data-y="${p.y}" x="${p.x}" y="${p.y}">${p[lang]}</text>`});
  dmap.innerHTML=s;

}

function gallery(d){const c=d.cover||0;
  return `<img class="cover" src="${d.photos[c].f}" alt="${d.photos[c][lang]}" data-p="${c}"><div class="gallery">${d.photos.map((p,j)=>`<figure data-p="${j}"><img src="${p.t}" alt="${p[lang]}" loading="lazy"><figcaption>${p[lang]}</figcaption></figure>`).join("")}</div>`}
const lb=document.getElementById("lb");let lbList=null,lbI=0;
function lbShow(i){lbI=(i+lbList.length)%lbList.length;const p=lbList[lbI];const im=document.getElementById("lbImg");im.src=p.f;im.alt=p[lang];
  document.getElementById("lbCap").textContent=p[lang];document.getElementById("lbCount").textContent=`${lbI+1} / ${lbList.length}`}
function lbOpen(list,i){lbList=list;lb.hidden=false;lbShow(i);document.getElementById("lbX").focus()}
function lbClose(){lb.hidden=true;lbList=null}
document.getElementById("lbX").addEventListener("click",lbClose);
document.getElementById("lbP").addEventListener("click",()=>lbShow(lbI-1));
document.getElementById("lbN").addEventListener("click",()=>lbShow(lbI+1));
lb.addEventListener("click",e=>{if(e.target===lb)lbClose()});
let lbTx=null;lb.addEventListener("touchstart",e=>{lbTx=e.touches[0].clientX},{passive:true});
lb.addEventListener("touchend",e=>{if(lbTx===null)return;const dx=e.changedTouches[0].clientX-lbTx;if(Math.abs(dx)>50)lbShow(lbI+(dx<0?1:-1));lbTx=null});
document.getElementById("dContent").addEventListener("click",e=>{const el=e.target.closest("[data-p]");if(!el||curDay<0)return;lbOpen(cur.days[curDay].photos,+el.dataset.p)});
function showDetail(i){
  const trip=cur,d=trip.days[i];const first=detail.hidden;
  detail.hidden=false;document.body.style.overflow="hidden";curDay=i;
  buildDetailMap(trip,i);
  const target=dayBBox(trip,i);
  if(first){const g=GEO[trip.geo];setVB([0,0,g.W,g.H]);requestAnimationFrame(()=>flyTo(dayBBox(trip,i)))}else{if(vb)setVB(vb);flyTo(target)}
  const g=GEO[trip.geo];const places=[...new Set(d.s)];
  document.getElementById("dContent").innerHTML=`<p class="d-date">${d.d}</p><p class="d-ch">${T(trip.chapters[d.ch])}</p>
    <h3 id="dTitle">${T({zh:d.zh,en:d.en})}</h3>${d.photos?gallery(d):""}<p>${T({zh:d.bz,en:d.be})}</p>
    ${places.length?`<ul class="d-stops">${places.map((k,j)=>`<li><b>${j+1}</b>${g.stops[k][lang]}</li>`).join("")}</ul>`:""}
    ${d.h?`<p class="stay">${T({zh:"住",en:"Stay"})}：${d.h}</p>`:""}
    <p class="log">${T({zh:"这一天还没有写。",en:"Nothing written for this day yet."})}</p>`;
  document.getElementById("dCount").textContent=lang==="zh"?`第 ${i+1} 天，共 ${trip.days.length} 天`:`Day ${i+1} of ${trip.days.length}`;
  document.getElementById("dPrev").disabled=i===0;document.getElementById("dNext").disabled=i===trip.days.length-1;
  document.getElementById("dbody").scrollTop=0;
  if(first)document.getElementById("dClose").focus();
}
function hideDetail(){if(detail.hidden)return;detail.hidden=true;document.body.style.overflow="";cancelAnimationFrame(anim);vb=null;
  const el=document.getElementById("day-"+curDay);if(el)el.scrollIntoView({block:"center"});curDay=-1}

let lblRaf=0;
const dpz=panZoom(dmap,{get:()=>vb,set:v=>{cancelAnimationFrame(anim);setVB(v)},onStart:()=>cancelAnimationFrame(anim),onEnd:()=>{cancelAnimationFrame(lblRaf);lblRaf=requestAnimationFrame(placeLabels)},
  get W(){return GEO[cur.geo].W},get H(){return GEO[cur.geo].H},get minW(){return GEO[cur.geo].W*0.02},get maxW(){return GEO[cur.geo].W*1.3},ctrlWheel:false,touchSingle:true});
dmap.addEventListener("click",e=>{const trip=cur,i=curDay;if(i<0)return;const g=GEO[trip.geo],m=dmap.getScreenCTM();if(!m)return;
  const now=new Set(trip.days[i].s);let best=null,bd=22;
  Object.keys(STOPDAYS[trip.id]).forEach(k=>{if(now.has(k))return;const p=g.stops[k];const d=Math.hypot(m.a*p.x+m.c*p.y+m.e-e.clientX,m.b*p.x+m.d*p.y+m.f-e.clientY);if(d<bd){bd=d;best=k}});
  if(!best)return;const ds=STOPDAYS[trip.id][best];const after=ds.find(x=>x>i);go(after!==undefined?after:ds[0])});
dmap.addEventListener("mousemove",e=>{if(dmap.classList.contains("dragging"))return;const trip=cur,i=curDay;if(i<0)return;const g=GEO[trip.geo],m=dmap.getScreenCTM();if(!m)return;
  const now=new Set(trip.days[i].s);const hit=Object.keys(STOPDAYS[trip.id]).some(k=>{if(now.has(k))return false;const p=g.stops[k];return Math.hypot(m.a*p.x+m.c*p.y+m.e-e.clientX,m.b*p.x+m.d*p.y+m.f-e.clientY)<22});
  dmap.style.cursor=hit?"pointer":""});
document.getElementById("dzIn").addEventListener("click",()=>dpz.zoomCenter(.6));
document.getElementById("dzOut").addEventListener("click",()=>dpz.zoomCenter(1/.6));
document.getElementById("dzReset").addEventListener("click",()=>flyTo(dayBBox(cur,curDay)));
document.getElementById("dPrev").addEventListener("click",()=>curDay>0&&go(curDay-1));
document.getElementById("dNext").addEventListener("click",()=>curDay<cur.days.length-1&&go(curDay+1));
document.getElementById("dClose").addEventListener("click",()=>{location.hash=cur.id});
addEventListener("keydown",e=>{if(!lb.hidden){if(e.key==="Escape")lbClose();else if(e.key==="ArrowLeft")lbShow(lbI-1);else if(e.key==="ArrowRight")lbShow(lbI+1);e.stopImmediatePropagation();return}if(detail.hidden)return;
  if(e.key==="Escape")location.hash=cur.id;
  else if(e.key==="ArrowLeft"&&curDay>0)go(curDay-1);
  else if(e.key==="ArrowRight"&&curDay<cur.days.length-1)go(curDay+1)});
addEventListener("resize",()=>{if(!detail.hidden){setVB(dayBBox(cur,curDay));placeLabels()}});

// ---------- routing ----------
function route(){if(!lb.hidden)lbClose();
  const [tid,dd]=decodeURIComponent((location.hash||"").slice(1)).split("/");
  const trip=TRIPS.find(t=>t.id===tid)||TRIPS[0];
  if(trip!==cur){cur=trip;hideDetail();render();scrollTo(0,0)}
  const i=dd?trip.days.findIndex(d=>d.d===dd):-1;
  if(i>=0)showDetail(i);else hideDetail();
}
function applyLang(){document.body.dataset.lang=lang;document.documentElement.lang=lang==="zh"?"zh-CN":"en";document.getElementById("langBtn").textContent=lang==="zh"?"EN":"中文"}
document.getElementById("langBtn").addEventListener("click",()=>{lang=lang==="zh"?"en":"zh";try{localStorage.setItem("lang",lang)}catch(e){}applyLang();render();if(curDay>=0)showDetail(curDay)});
addEventListener("hashchange",route);
applyLang();route();
